86	type ReasonDialogProps = {
87	  paymentId: string;
88	  action: "reject" | "void";
89	  triggerLabel: string;
90	  title: string;
91	  description: string;
92	  confirmLabel: string;
93	  busyLabel: string;
94	  successMessage: string;
95	};
96	
97	function ReasonDialog(p: ReasonDialogProps) {
98	  const router = useRouter();
99	  const [open, setOpen] = useState(false);
100	  const [reason, setReason] = useState("");
101	  const [touched, setTouched] = useState(false);
102	  const [busy, setBusy] = useState(false);
103	
104	  const tooShort = reason.trim().length < MIN_REASON;
105	  const showError = touched && tooShort;
106	  const fieldId = `${p.action}-reason-${p.paymentId}`;
107	
108	  function onOpenChange(next: boolean) {
109	    if (busy) return;
110	    setOpen(next);
111	    if (!next) {
112	      setReason("");
113	      setTouched(false);
114	    }
115	  }
116	
117	  async function confirm() {
118	    setTouched(true);
119	    if (tooShort) return;
120	    setBusy(true);
121	    const res = await callApi(`/api/payments/${p.paymentId}/${p.action}`, {
122	      method: "POST",
123	      body: { reason: reason.trim() },
124	    });
125	    setBusy(false);
126	    if (!res.ok) {
127	      toast.error(res.error);
128	      return;
129	    }
130	    toast.success(p.successMessage);
131	    setOpen(false);
132	    setReason("");
133	    setTouched(false);
134	    router.refresh();
135	  }
136	
137	  return (
138	    <>
139	      <Button type="button" size="sm" variant="destructive" onClick={() => setOpen(true)}>
140	        {p.triggerLabel}
141	      </Button>
142	      <AlertDialog open={open} onOpenChange={onOpenChange}>
143	        <AlertDialogContent>
144	          <AlertDialogHeader>
145	            <AlertDialogTitle>{p.title}</AlertDialogTitle>
146	            <AlertDialogDescription>{p.description}</AlertDialogDescription>
147	          </AlertDialogHeader>
148	          <div className="flex flex-col gap-2">
149	            <Label htmlFor={fieldId}>Reason (at least {MIN_REASON} characters)</Label>
150	            <Textarea
151	              id={fieldId}
152	              value={reason}
153	              onChange={(e) => setReason(e.target.value)}
154	              onBlur={() => setTouched(true)}
155	              aria-invalid={showError}
156	              aria-describedby={showError ? `${fieldId}-error` : undefined}
157	              disabled={busy}
158	              placeholder="Why are you doing this?"
159	            />
160	            {showError && (
161	              <p id={`${fieldId}-error`} className="text-sm text-destructive">
162	                Enter a reason of at least {MIN_REASON} characters.
163	              </p>
164	            )}
165	          </div>
166	          <AlertDialogFooter>
167	            <AlertDialogCancel disabled={busy}>Cancel</AlertDialogCancel>
168	            <Button type="button" variant="destructive" onClick={confirm} disabled={busy}>
169	              {busy ? p.busyLabel : p.confirmLabel}
170	            </Button>
171	          </AlertDialogFooter>
172	        </AlertDialogContent>
173	      </AlertDialog>
174	    </>
175	  );
176	}
