10	import { cn } from "@/lib/utils";
11	import { getGatewayBill, type GatewayBillDto } from "@/server/services/gateway";
12	
13	export const metadata = { title: "Payment status" };
14	export const dynamic = "force-dynamic";
15	
16	const MESSAGE: Record<GatewayBillDto["status"], string> = {
17	  pending: "We are waiting for the gateway to confirm your payment.",
18	  paid: "Payment received. Thank you.",
19	  failed: "The payment failed. You can start a new payment from your tenancy page.",
20	};
21	
22	// R31: strictly read-only. Only the gateway webhook settles a bill, so the `paid` query parameter is never
23	// read here; the status shown is whatever the database says.
24	export default async function PaymentReturnPage({
25	  searchParams,
26	}: {
27	  searchParams: Promise<{ bill_id?: string | string[] }>;
28	}) {
29	  const { bill_id } = await searchParams;
30	  const billId = Array.isArray(bill_id) ? bill_id[0] : bill_id;
31	
32	  const supabase = await createClient();
33	  const { data, error } = await supabase.auth.getUser();
34	  if (error || !data.user) redirect("/login");
35	
36	  let bill: GatewayBillDto | null = null;
37	  if (billId) {
38	    try {
39	      bill = await getGatewayBill({ userId: data.user.id }, billId);
40	    } catch (e) {
41	      // Unknown, malformed or someone else's bill all look the same (R38); anything else is a real error.
42	      if (!(e instanceof ApiError && e.status === 404)) throw e;
43	    }
44	  }
45	
46	  return (
47	    <Card className="max-w-lg">
48	      <CardHeader>
49	        <CardTitle>Payment status</CardTitle>
50	        {bill && <CardDescription>The status below is read from our records.</CardDescription>}
51	      </CardHeader>
52	      <CardContent className="flex flex-col gap-4">
53	        {bill ? (
54	          <>
55	            <div className="flex items-center gap-2">
56	              <Badge variant={bill.status === "paid" ? "default" : bill.status === "failed" ? "destructive" : "secondary"}>
57	                {bill.status === "paid" ? "Paid" : bill.status === "failed" ? "Failed" : "Pending"}
58	              </Badge>
59	              <p className="text-sm" data-testid="bill-status-message">
60	                {MESSAGE[bill.status]}
61	              </p>
62	            </div>
63	            <dl className="grid grid-cols-[max-content_1fr] gap-x-4 gap-y-1 text-sm">
64	              <dt className="text-muted-foreground">Bill id</dt>
65	              <dd className="font-mono break-all">{bill.billId}</dd>
66	              <dt className="text-muted-foreground">Amount</dt>
67	              <dd>{formatSen(bill.amountSen)}</dd>
68	            </dl>
69	          </>
